function runbookTaskForm(params) {
  // Async (CMP registers it with isAsync). Runs once when the Run Task form
  // loads, then watches the Task dropdown. For each task chosen it asks the
  // Runbook Tasks webhook for that task's inputs, rebuilds the
  // action-input.task_inputs Dynamic Panel from them, and shows a credentials
  // box when CloudBolt has no way to log in to the VM. The box is plain
  // HTML, not survey questions, so the password never joins the submitted
  // payload (CloudBolt writes that to the job log); the webhook saves it on
  // the VM instead, as CloudBolt's own credential prompt does.
  var survey = this.survey;
  var done = this.returnResult.bind(this);
  if (!survey) { done("error: no survey instance is available to the form function."); return; }
  if (survey.cbServerTaskForm) { done("ready"); return; }
  survey.cbServerTaskForm = true;

  var HOOK = "/api/v3/cmp/inboundWebHooks/runbook-tasks/run/";
  var TASK = "action-input.task";
  var PANEL = "action-input.task_inputs";
  var NOTE = "runbook_task_note";
  var state = { task: null, blocking: "", credentials: null, request: 0 };

  function escapeHtml(value) {
    return String(value === undefined || value === null ? "" : value)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function paragraph(text, css) {
    return "<p" + (css ? " class=\"" + css + "\"" : "") + ">" + escapeHtml(text) + "</p>";
  }
  function query(values) {
    return Object.keys(values).map(function (key) {
      var value = values[key];
      return encodeURIComponent(key) + "=" + encodeURIComponent(value === undefined || value === null ? "" : value);
    }).join("&");
  }
  function serverIds() {
    var ids = survey.getValue("object_ids");
    return typeof ids === "string" ? ids : (ids ? JSON.stringify(ids) : "");
  }
  function readJson(response) {
    return response.text().then(function (text) {
      var body;
      try { body = JSON.parse(text); } catch (e) { body = { error: "non-JSON reply (HTTP " + response.status + "): " + text.slice(0, 300) }; }
      if (!body || typeof body !== "object") body = { error: "unexpected reply (HTTP " + response.status + ")" };
      if (!response.ok && !body.error) body.error = "HTTP " + response.status;
      return body;
    });
  }
  function setNote(html) {
    var note = survey.getQuestionByName(NOTE);
    if (!note) return;
    note.html = html || "";
    note.visible = !!html;
  }

  function replacePanel(spec) {
    var old = survey.getQuestionByName(PANEL);
    var container = old && old.parent ? old.parent : survey.pages[0];
    var index = old ? container.elements.indexOf(old) : container.elements.length;
    var elements = (spec && spec.elements) || [];
    // Built in full before it joins the page, so the first render has every property.
    var panel = Survey.Serializer.createClass("paneldynamic");
    panel.name = PANEL;
    panel.fromJSON({
      title: "Task inputs",
      description: spec && spec.description ? spec.description : "",
      templateElements: elements,
      maxPanelCount: 1,
      allowAddPanel: false,
      allowRemovePanel: false
    });
    if (old) container.removeElement(old);
    container.addElement(panel, index);
    panel.panelCount = elements.length ? 1 : 0;
    panel.minPanelCount = elements.length ? 1 : 0;
    panel.visible = elements.length > 0;
  }

  function credentialsHtml(info) {
    var hosts = (info.needed || []).join(", ");
    if (!info.can_save) {
      return paragraph("CloudBolt has no credentials to log in to " + hosts + ". Ask an administrator to set them on the " +
        "VM or on the Remote Script, then run the task.", "text-danger");
    }
    return "<div class=\"cb-runbook-task-credentials\">" +
      paragraph("CloudBolt has no credentials to log in to " + hosts + ". Save a username and password on the VM " +
        "(stored encrypted, and used by this and later tasks):") +
      "<div class=\"mb-2\"><label class=\"form-label\" for=\"cb-runbook-task-username\">Username</label>" +
      "<input type=\"text\" class=\"form-control\" id=\"cb-runbook-task-username\" autocomplete=\"off\"></div>" +
      "<div class=\"mb-2\"><label class=\"form-label\" for=\"cb-runbook-task-password\">Password</label>" +
      "<input type=\"password\" class=\"form-control\" id=\"cb-runbook-task-password\" autocomplete=\"new-password\"></div>" +
      "<button type=\"button\" class=\"sd-btn sd-btn--action\" id=\"cb-runbook-task-save\">Save credentials</button> " +
      "<span id=\"cb-runbook-task-save-status\"></span></div>";
  }

  function load(task) {
    var mine = ++state.request;
    state.task = task || null;
    state.blocking = "";
    state.credentials = null;
    if (!task) { replacePanel(null); setNote(""); return; }
    setNote(paragraph("Loading the task's inputs...", "custom-order-form-loading"));
    fetch(HOOK + "?" + query({ source: "inputs", server: survey.getValue("object_id"), servers: serverIds(), task: task }), {
      credentials: "same-origin", headers: { "Accept": "application/json" }
    })
      .then(readJson)
      .then(function (reply) {
        if (mine !== state.request) return;
        if (reply.error || !reply.panel) {
          replacePanel(null);
          state.blocking = reply.error || "Could not load the task's inputs.";
          setNote(paragraph(state.blocking, "text-danger"));
          return;
        }
        var spec = reply.panel;
        replacePanel(spec);
        var notes = [];
        if (spec.blocking && spec.blocking.length) {
          state.blocking = "This task requires " + spec.blocking.join(", ") + ", which Run Task cannot carry " +
            "(a password or a CloudBolt object). Run the script from its own action instead.";
          notes.push(paragraph(state.blocking, "text-danger"));
        }
        if (spec.omitted && spec.omitted.length) {
          notes.push(paragraph("Left out, because Run Task does not carry them: " + spec.omitted.join(", ") + "."));
        }
        var credentials = reply.credentials || {};
        if (credentials.needed && credentials.needed.length) {
          state.credentials = credentials;
          notes.push(credentialsHtml(credentials));
        }
        setNote(notes.join(""));
      })
      .catch(function (error) {
        if (mine !== state.request) return;
        state.blocking = "Could not load the task's inputs: " + error;
        setNote(paragraph(state.blocking, "text-danger"));
      });
  }

  function saveCredentials() {
    var username = document.getElementById("cb-runbook-task-username");
    var password = document.getElementById("cb-runbook-task-password");
    var status = document.getElementById("cb-runbook-task-save-status");
    var csrf = window.c2 && window.c2.settings ? window.c2.settings.CSRFToken : "";
    if (status) status.textContent = "Saving...";
    fetch(HOOK, {
      method: "POST",
      credentials: "same-origin",
      headers: { "Content-Type": "application/json", "Accept": "application/json", "X-CSRFToken": csrf },
      body: JSON.stringify({
        source: "credentials",
        server: String(survey.getValue("object_id") || ""),
        username: username ? username.value : "",
        password: password ? password.value : ""
      })
    })
      .then(readJson)
      .then(function (reply) {
        if (password) password.value = "";
        if (reply.error || !reply.saved) {
          if (status) status.textContent = "Not saved: " + (reply.error || "unexpected reply");
          return;
        }
        load(state.task);
      })
      .catch(function (error) {
        if (password) password.value = "";
        if (status) status.textContent = "Not saved: " + error;
      });
  }

  // The task list comes from the webhook too, not choicesByUrl: CMP adds the
  // object_ids question only on bulk runs, and a choicesByUrl URL that names
  // a missing question is never requested. CMP also adds object_id after the
  // survey is built, so wait for it.
  function loadTasks(attempt) {
    var question = survey.getQuestionByName(TASK);
    var objectId = survey.getValue("object_id");
    if (!question) return;
    if (!objectId) {
      if (attempt < 40) { setTimeout(function () { loadTasks(attempt + 1); }, 250); return; }
      setNote(paragraph("The form did not receive the VM's id (object_id).", "text-danger"));
      return;
    }
    question.placeholder = "Loading tasks...";
    fetch(HOOK + "?" + query({ source: "tasks", server: objectId, servers: serverIds() }), {
      credentials: "same-origin", headers: { "Accept": "application/json" }
    })
      .then(readJson)
      .then(function (reply) {
        var options = reply.options || [];
        question.choices = options.map(function (option) { return { value: option.value, text: option.title }; });
        question.placeholder = options.length ? "Select a task..." : "No tasks fit this VM";
        if (reply.error) setNote(paragraph("Could not load the tasks: " + reply.error, "text-danger"));
      })
      .catch(function (error) {
        question.placeholder = "Select...";
        setNote(paragraph("Could not load the tasks: " + error, "text-danger"));
      });
  }

  document.addEventListener("click", function (event) {
    if (!event.target || event.target.id !== "cb-runbook-task-save") return;
    event.preventDefault();
    saveCredentials();
  });
  survey.onValueChanged.add(function (sender, options) {
    if (options.name === TASK) load(options.value);
  });
  survey.onValidateQuestion.add(function (sender, options) {
    if (options.name !== TASK || !options.value || options.value !== state.task) return;
    if (state.blocking) {
      options.error = state.blocking;
    } else if (state.credentials) {
      options.error = "CloudBolt has no credentials for " + state.credentials.needed.join(", ") +
        ". Save them above, or ask an administrator to set them.";
    }
  });
  loadTasks(0);
  if (survey.getValue(TASK)) load(survey.getValue(TASK));
  done("ready");
}
